const $=s=>document.querySelector(s);
const main=$('#main');
const storageKey=(key,recovered=false)=>key==='sessions'?`ga:online:v1:${recovered?'recovered:':''}sessions`:`ga:${recovered?'recovered:':''}${key}`;
function invitationRoom(){const value=(new URLSearchParams(location.search).get('room')||'').trim().toUpperCase();return /^[A-Z0-9_-]{4,40}$/.test(value)?value:'';}
function consumeInvitation(){const url=new URL(location.href);if(url.searchParams.has('room')){url.searchParams.delete('room');history.replaceState(null,'',url);}}
if(invitationRoom()&&!location.hash)history.replaceState(null,'',location.pathname+location.search+'#/tavern');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=v=>Number(v||0).toLocaleString('zh-CN',{maximumFractionDigits:2});
const fmt=v=>Number(v||0).toFixed(2);
const uid=()=>globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random()}`;
const icons={arrow:'↗',next:'→',back:'←'};
let caseSelections={},activeReadId=null,suspendReading=false,dockObserver=null,avatarEditor=null;
if('scrollRestoration' in history)history.scrollRestoration='manual';
let memory={},storageFailed=false,badStorage={},brokenKeys=new Set();
function getStore(key,fallback){try{const raw=localStorage.getItem(storageKey(key));let value;const valid=v=>v==null||(['notes','trash'].includes(key)?Array.isArray(v)&&v.every(n=>n&&typeof n.id==='string'&&/^[a-zA-Z0-9_-]{1,100}$/.test(n.id)&&typeof n.body==='string'&&typeof n.title==='string'):key==='progress'?typeof v==='object'&&!Array.isArray(v)&&Object.values(v).every(p=>p&&Number.isFinite(p.percent)&&p.percent>=0&&p.percent<=100&&Number.isFinite(p.scroll)&&p.scroll>=0):key==='sessions'?typeof v==='object'&&!Array.isArray(v)&&Object.entries(v).every(([id,s])=>/^[a-zA-Z0-9_-]{1,100}$/.test(id)&&s&&typeof s==='object'&&typeof s.token==='string'&&typeof s.agentToken==='string'&&typeof s.name==='string'):true);try{value=JSON.parse(raw);if(!valid(value))throw new Error('shape');return value??fallback;}catch{badStorage[key]=raw;brokenKeys.add(key);try{value=JSON.parse(localStorage.getItem(storageKey(key,true)));return valid(value)?value??fallback:fallback;}catch{return fallback;}}}catch{storageFailed=true;return memory[key]??fallback;}}
function saveStore(key,value){memory[key]=value;try{localStorage.setItem(storageKey(key,brokenKeys.has(key)),JSON.stringify(value));return true;}catch{storageFailed=true;toast('本机存储不可用，本次修改暂存内存。请导出备份。',true);return false;}}
const validRecord=v=>v&&typeof v==='object'&&!Array.isArray(v);
const safeId=v=>typeof v==='string'&&/^[a-zA-Z0-9_-]{1,100}$/.test(v);
let rawProgress=getStore('progress',{}),rawNotes=getStore('notes',[]),rawSessions=getStore('sessions',{});
for(const [key,v,valid] of [['progress',rawProgress,validRecord(rawProgress)],['notes',rawNotes,Array.isArray(rawNotes)&&rawNotes.every(n=>n&&safeId(n.id)&&typeof n.body==='string'&&typeof n.title==='string')],['sessions',rawSessions,validRecord(rawSessions)]]){if(!valid){brokenKeys.add(key);badStorage[key]=v;}}
let corruptedStorage=brokenKeys.size>0;
let progress=validRecord(rawProgress)?rawProgress:{},notes=Array.isArray(rawNotes)?rawNotes.filter(n=>n&&safeId(n.id)&&typeof n.body==='string'&&typeof n.title==='string'):[],sessions=validRecord(rawSessions)?rawSessions:{},config=null,currentState=null,pollId=null,globe=null,route='',viewKey='',serverOffset=0,autoRotate=false;
function toast(msg,error=false){const el=$('#toast');el.textContent=msg;el.className='show'+(error?' error':'');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.className='',4500);}
function go(path){if(location.hash==='#/'+path)render();else location.hash='/'+path;}
function button(label,action,cls='button'){return `<button class="${cls}" data-action="${action}">${label}</button>`;}
function link(label,path,cls='text-link'){return `<a class="${cls}" href="#/${path}">${label}</a>`;}
function sectionLabel(){return '';}
function readPct(){return Math.round(chapters.reduce((s,c)=>s+(progress[c.id]?.percent||0),0)/chapters.length);}
function header(active){$('#site-header').innerHTML=`<a href="#/home" class="brand" aria-label="增长黑客首页"><span class="brand-mark">G<span>↗</span></span><span>增长黑客</span></a><nav aria-label="主导航"><a href="#/map" ${active==='map'||active==='read'?'aria-current="page"':''}>阅读地图</a><a href="#/lab" ${active==='lab'?'aria-current="page"':''}>增长实验室</a><a href="#/cases" ${active==='cases'?'aria-current="page"':''}>案例拆解</a><a href="#/notes" ${active==='notes'?'aria-current="page"':''}>阅读札记 <span class="note-count">${notes.length}</span></a></nav><a href="#/tavern" class="header-tavern">增长酒馆 <span>↗</span></a>`;}
function footer(){ $('#site-footer').innerHTML=`<p class="footer-source">《增长黑客》交互阅读<br><span>${bookMeta.authors} · 中信2018年中文版</span></p><nav class="footer-links" aria-label="页脚导航"><a href="#/map">阅读地图</a><a href="#/notes">我的札记</a><a href="#/tavern">增长酒馆</a></nav><p class="footer-note">学习型二次解读，游戏规则为教学改编。</p>`; }
function home(){const resume=chapters.find(c=>(progress[c.id]?.percent||0)>0&&(progress[c.id]?.percent||0)<100)||chapters[0];main.innerHTML=classroomHome({bookMeta,readPercent:readPct(),resumeId:resume.id,sessions,previewSrc:'/assets/classroom/tavern-preview.webp'});}
function mapPage(){main.innerHTML=`<div class="page map-page"><div class="page-heading"><div><h1>阅读地图</h1><p>六个主题，按你关心的问题进入。</p></div><div class="map-landscape"><img src="/assets/figma/landscape.png" alt="墨色地景与朱红太阳" width="2172" height="724"></div></div><section class="map-directory"><div>${chapters.map(c=>`<a class="chapter-row" href="#/read/${c.id}"><span class="chapter-no">${c.no}</span><div><h3>${c.label}</h3><span class="chapter-bar"><i style="width:${progress[c.id]?.percent||0}%"></i></span></div><span class="chapter-duration">${progress[c.id]?.percent?`${progress[c.id].percent}% 已读`:'未开始'}</span><b>↗</b></a>`).join('')}</div></section><section class="map-playbook"><div><h2>把方法带进酒馆</h2><p>同一种产品、相同的起点。用六次决策，看看你的判断会带来什么结果。</p></div>${link('进入增长酒馆 →','tavern','button solid')}</section><p class="editor-note">阅读主题为本项目重新编排，不等同于原书目录。</p></div>`;}
function readPage(id){const c=chapters.find(x=>x.id===id)||chapters[0];main.innerHTML=`<div class="reading-progress" id="reading-progress"></div><div class="page read-page"><div class="read-topline">${link('← 阅读地图','map')}<span>${c.no} / 06 · 约 ${c.time} 分钟</span><button class="quiet-button" data-action="reading-settings">Aa 阅读设置</button></div><div class="reading-layout"><aside class="read-index"><span class="eyebrow">本篇目录</span>${c.sections.map((s,i)=>`<a href="#section-${i}" data-scroll="section-${i}">${String(i+1).padStart(2,'0')} ${s[0]}</a>`).join('')}</aside><article class="chapter-article"><p class="eyebrow">${c.tag}</p><h1>${c.title.replace('\n','')}</h1><p class="article-intro">${c.intro}</p><blockquote><span class="quote-label">阅读提示 · 本项目撰写</span>${c.quote}</blockquote>${c.id==='activation'?'<figure class="value-figure"><img src="/assets/figma/value-platforms.png" alt="三个逐级上升的纸面平台，表现从进入到体验价值的过程" width="2172" height="724"><figcaption>进入产品 → 完成核心任务 → 体验价值 · 教学路径</figcaption></figure>':''}${c.sections.map((s,i)=>`<section class="article-section" id="section-${i}"><h2>${s[0]}</h2>${s.slice(1).map(p=>`<p>${p}</p>`).join('')}</section>`).join('')}<section class="takeaway"><p>${c.takeaway}</p><div>${link(c.action+' ↗',c.id==='growth-loop'?'cases':c.id==='economics'?'tavern':'lab','button solid')}<button class="button outline" data-action="note-from-chapter" data-id="${c.id}">写一点思考</button></div></section><div class="article-next">${c.next?link(`<span>下一条路径</span><h3>${chapters.find(x=>x.id===c.next).label} →</h3>`,`read/${c.next}`):link('<span>方法已经在手</span><h3>走进增长酒馆 →</h3>','tavern')}</div><p class="editor-note">${bookMeta.note}</p></article></div></div>`;const from=location.hash.replace(/^#\/?/,'').split('/');if(from[2]==='from'&&/^[A-Za-z0-9_-]{1,100}$/.test(from[3]||'')&&Number(from[4])>=1&&Number(from[4])<=6){$('.read-topline')?.insertAdjacentHTML('afterend',`<nav class="reading-return"><a href="#/tavern/${esc(from[3])}/review/${Number(from[4])}">← 回到第 ${Number(from[4])} 轮复盘</a><span>带着这次判断，读相关的方法。</span></nav>`);}activeReadId=c.id;suspendReading=true;const restoreScroll=progress[c.id]?.percent<100?Number(progress[c.id]?.scroll||0):0;requestAnimationFrame(()=>{window.scrollTo({left:0,top:restoreScroll,behavior:'instant'});requestAnimationFrame(()=>{suspendReading=false;updateReading();});});}
function labPage(){main.innerHTML=`<div class="page lab-page"><section class="lab-banner"><div><h1>增长实验室</h1><p>调整变量，观察三个教学模型的结果。</p></div></section><div class="lab-intro"><p>以下模型用于理解机制，不是真实产品预测。</p></div><section class="lab-experiment" id="lab-retention"><div class="experiment-label"><span>01</span><h3>先修漏桶，<br>还是先加水？</h3><p>每轮固定新增100人，初始100人。<br>观察6轮后，留存如何影响活跃规模。</p>${link('延伸阅读：留存与同期群 ↗','read/retention')}</div><div class="experiment-work"><div class="control-label"><label for="retention-input">每轮留存率</label><output id="retention-value">70%</output></div><input id="retention-input" type="range" min="10" max="95" step="5" value="70"><div id="retention-chart" class="bar-chart" role="img" aria-label="六回合活跃用户变化"></div><div class="experiment-result" id="retention-result"></div><p class="model-note">模型：下一轮活跃 = 上一轮活跃 × 留存率 + 100，逐轮取整。没有渠道、成本和人群差异，不作为经营预测。</p></div></section><section class="lab-experiment"><div class="experiment-label"><span>02</span><h3>更多流量，<br>还是更好体验？</h3><p>比较访问人数与激活率的变化，<br>看哪一环带来更多首次价值。</p>${link('延伸阅读：第一次价值 ↗','read/activation')}</div><div class="experiment-work"><div class="control-label"><label for="visitors-input">每期访问人数</label><output id="visitors-value">1,000</output></div><input id="visitors-input" type="range" min="200" max="3000" step="100" value="1000"><div class="control-label"><label for="activation-input">核心行为完成率</label><output id="activation-value">20%</output></div><input id="activation-input" type="range" min="5" max="80" step="5" value="20"><div class="conversion-flow"><div><span>访问</span><b id="conversion-visitors">1,000</b></div><i>→</i><div><span>获得首次价值</span><b id="conversion-active">200</b></div></div><div class="experiment-result" id="conversion-result"></div><p class="model-note">模型：激活人数 = 访问人数 × 完成率。这里不推断收益，也不输出统计显著性；真实实验需核对成本、样本与后续留存。</p></div></section><section class="lab-experiment"><div class="experiment-label"><span>03</span><h3>好想法很多，<br>先验证哪一个？</h3><p>用 ICE 把判断摊开讨论。<br>评分表达你的预期，不代表客观成功概率。</p>${link('延伸阅读：实验循环 ↗','read/experiments')}</div><div class="experiment-work"><div class="ice-controls">${[['impact','影响','改变有多大'],['confidence','信心','证据有多足'],['ease','便利','实施有多容易']].map(([id,name,help])=>`<div><label for="ice-${id}">${name}<small>${help}</small></label><input id="ice-${id}" type="range" min="1" max="10" value="5"><output id="ice-${id}-value">5</output></div>`).join('')}</div><div class="ice-result"><span>教学版 ICE 平均分</span><b id="ice-score">5.0</b><p id="ice-text"></p></div><p class="model-note">本项目采用(影响＋信心＋便利)÷3作为教学排序。主观评分不能替代用户研究、合规判断或真实实验。</p></div></section><section class="lab-to-tavern"><h2>现在，把这些判断<br>带到同一张桌上。</h2><p>四位经营者，同一种产品，六回合。<br>与自己的 Agent 合作，把有限资源放在你相信的事情上。</p>${link('走进 Agent 增长酒馆 ↗','tavern','button light')}<span class="small">可直接练习 · 无需读完 · 明确标识脚本席</span></section></div>`;updateLabs();mountLabLearning(document);}
function updateLabs(){if(!$('#retention-input'))return;let ret=+$('#retention-input').value/100,u=100;const data=Array.from({length:6},()=>u=Math.round(u*ret+100));$('#retention-value').textContent=`${Math.round(ret*100)}%`;$('#retention-chart').innerHTML=data.map((n,i)=>`<div><b>${n}</b><i style="height:${n/650*130}px"></i><span>R${i+1}</span></div>`).join('');$('#retention-result').innerHTML=`第6轮拥有 <strong>${data[5]} 位</strong>活跃用户。<span>${ret>=.8?'高留存让每一轮新增更多地沉淀下来。':ret<=.4?'新增不断进入，流失也在带走多数积累。':'留存与新增共同决定增长底座，两个入口都值得观察。'}</span>`;const v=+$('#visitors-input').value,a=+$('#activation-input').value;$('#visitors-value').textContent=num(v);$('#activation-value').textContent=a+'%';$('#conversion-visitors').textContent=num(v);$('#conversion-active').textContent=num(Math.round(v*a/100));$('#conversion-result').innerHTML=`预计 <strong>${Math.round(v*a/100)} 人</strong>完成核心行为。<span>在此模型中，完成率提高5个百分点，相当于增加${Math.round(v*.05)}位激活用户。实际投入成本仍需另算。</span>`;const vals=['impact','confidence','ease'].map(x=>{const n=+$('#ice-'+x).value;$('#ice-'+x+'-value').textContent=n;return n;});$('#ice-score').textContent=(vals.reduce((s,v)=>s+v)/3).toFixed(1);$('#ice-text').textContent=vals[1]<=3?'信心较低：先找证据，或把实验缩小到可承担的范围。':vals[2]<=3?'实施较难：先验证最关键的假设，减少一次性投入。':'适合与其他想法比较排序。先写下主指标与护栏，再开始。';}
function casePage(id){const selected=cases.find(c=>c.id===id);main.innerHTML=`<div class="page cases-page"><div class="page-heading"><div><h1>案例拆解</h1><p>三个明确标注的教学设想。<br>没有神奇秘方，只有情境、判断和后果。</p></div><div class="case-heading-art"><img src="/assets/figma/case-path.png" alt="红色折纸路径在深墨空间中分岔" width="1171" height="1343"></div></div><nav class="case-tabs" aria-label="案例选择">${cases.map(c=>`<a href="#/cases/${c.id}" ${c.id===(selected||cases[0]).id?'aria-current="page"':''}>${c.category.split(' · ')[0]}</a>`).join('')}</nav><div id="case-detail">${caseDetail(selected||cases[0])}</div></div>`;}
function caseDetail(c){return `<section class="case-layout"><aside><span class="eyebrow">${c.category}</span><h2>${c.title.replace('\n','')}</h2><p class="small muted">${c.context}</p><div class="case-route"><span>问题</span><i>↓</i><span>假设</span><i>↓</i><span>行动</span><i>↓</i><span>复盘</span></div></aside><div><div class="case-problem"><h3>我们遇到了什么？</h3><p>${c.problem}</p></div><div class="case-choice"><h3>你会先做哪一个选择？</h3><div>${c.options.map((o,i)=>`<button class="case-option" data-action="case-option" data-case="${c.id}" data-index="${i}" aria-pressed="false"><span>${String.fromCharCode(65+i)}</span><div><b>${o.name}</b><small>${o.detail}</small></div><i>→</i></button>`).join('')}</div></div><div class="case-outcome" id="case-outcome" aria-live="polite"><p>选择一个行动，看看它改变了哪一环，<br>以及哪些问题仍然没有答案。</p></div><div class="case-bottom"><p>${c.insight}</p>${link('回到知识：'+chapters.find(x=>x.id===c.chapter).label+' ↗','read/'+c.chapter)}<button class="text-link" data-action="case-note" data-id="${c.id}">把判断写进札记 +</button></div></div></section>`;}

let noteDraftManager=null;
function noteDrafts(){return noteDraftManager||(noteDraftManager=createNoteDrafts());}
function captureNoteDraft(){const form=$('#note-form');if(!form)return;const result=noteDrafts().capture(form);if(result.message)setText($('#note-save-status'),result.message);}
function restoreNoteDraft(savedNote,force=false){const form=$('#note-form');if(!form)return;const result=noteDrafts().restore(form,{savedNote,force});if(result.message)setText($('#note-save-status'),result.message);const old=$('#note-draft-choices');old?.remove();if(result.found){const actions=document.createElement('div');actions.id='note-draft-choices';actions.className='note-draft-choices';actions.innerHTML=(result.conflict?'<button type="button" class="quiet-button" data-action="restore-note-draft">恢复未保存草稿</button>':'')+'<button type="button" class="quiet-button" data-action="discard-note-draft">丢弃未保存草稿</button>';form.append(actions);}}
function updateClassroomSurfaces(s){
 setMarkup($('#classroom-mission-slot'),s.phase==='lobby'?missionMarkup(s):'');
 setMarkup($('#classroom-round-summary-slot'),roundSummaryMarkup(s));
 setMarkup($('#classroom-result-slot'),s.phase==='finished'?resultMarkup(s,roomUi.reviewRound,config?.actions||[]):'');
 const arena=$('.v3-room');if(arena)arena.dataset.sceneExpanded=String(Boolean(roomUi.sceneExpanded));
 document.querySelectorAll('.scene-toggle').forEach(button=>{button.textContent=roomUi.sceneExpanded?'收起圆桌':'展开圆桌';button.setAttribute('aria-pressed',String(Boolean(roomUi.sceneExpanded)));});
}
