function notesSourceBanner(note){const markup=noteSourceMarkup(note?.source);if(markup)$('#note-form')?.insertAdjacentHTML('beforebegin',markup);}

function notesPage(id){let note=notes.find(n=>n.id===id)||null;main.innerHTML=`<div class="page notes-page"><div class="page-heading"><div><h1>阅读札记</h1><p>写下问题、证据与下一次行动。</p></div></div><div class="notes-toolbar"><p><b>${notes.length}</b> 条思考 <span class="muted">/ ${storageFailed?'内存暂存，请导出':'本机保存'}</span></p><div><button class="text-link" data-action="export-notes">导出备份 ↓</button>${getStore('trash',[]).length?'<button class="text-link" data-action="restore-note">恢复最近删除 ↶</button>':''}<label class="text-link import-label">导入恢复 ↑<input type="file" id="import-notes" accept="application/json,.json"></label><button class="button solid small-button" data-action="new-note">新增札记 +</button></div></div>${corruptedStorage?'<div class="notice error">检测到本地记录格式异常，未覆盖旧数据。可先导出原始数据备份。<button class="text-link" data-action="export-raw">导出原始数据</button></div>':''}${storageFailed?'<div class="notice error">浏览器存储不可用。当前修改仅暂存内存，关闭页面前请导出。</div>':''}<section class="notes-layout"><aside class="notes-index">${notes.length?notes.slice().sort((a,b)=>b.updated-a.updated).map(n=>`<a href="#/notes/${n.id}" ${note?.id===n.id?'aria-current="page"':''}><small>${new Date(n.updated).toLocaleDateString('zh-CN')}</small><h3>${esc(n.title||'未命名札记')}</h3><p>${esc(n.body.slice(0,46))}${n.body.length>46?'…':''}</p><span>${esc(n.tag||'自由思考')}</span></a>`).join(''):'<div class="empty-notes"><h3>第一页，留给你。</h3><p>这里没有替你写好的感悟。<br>从一个问题开始就好。</p></div>'}</aside><div class="note-editor"><form id="note-form" data-id="${note?.id||''}"><label class="sr-only" for="note-title">札记标题</label><input id="note-title" name="title" maxlength="100" placeholder="给这个想法起个名字" value="${esc(note?.title||'')}"><label for="note-tag" class="small muted">关联知识</label><select id="note-tag" name="tag"><option value="自由思考">自由思考</option>${chapters.map(c=>`<option ${note?.tag===c.tag?'selected':''}>${c.tag}</option>`).join('')}<option ${note?.tag==='酒馆复盘'?'selected':''}>酒馆复盘</option></select><label class="sr-only" for="note-body">札记正文</label><textarea id="note-body" name="body" required maxlength="20000" placeholder="我观察到的事实是……&#10;&#10;我目前的解释是……&#10;&#10;下一次，我想验证……">${esc(note?.body||'')}</textarea><div class="note-editor-bottom"><span id="note-save-status">${note?'上次保存 '+new Date(note.updated).toLocaleString('zh-CN'):'输入后点击保存。'}</span><div>${note?'<button class="quiet-button danger" type="button" data-action="delete-note" data-id="'+note.id+'">删除</button>':''}<button type="submit" class="button solid">保存札记 →</button></div></div></form><p class="small muted">建议定期导出备份。清理浏览器数据、隐私模式或更换设备可能使本地记录丢失。</p></div></section></div>`;notesSourceBanner(note);restoreNoteDraft(note);}

async function api(path,options={}){
 const {token,body,method='GET'}=options,roomRequest=path==='/api/rooms'||path.startsWith('/api/rooms/'),controller=roomRequest?new AbortController():null,signal=controller?.signal||options.signal;
 let timer;const forwardAbort=()=>controller?.abort(options.signal?.reason);
 if(controller){roomRequests.add(controller);if(options.signal?.aborted)forwardAbort();else options.signal?.addEventListener('abort',forwardAbort,{once:true});timer=setTimeout(()=>controller.abort(new DOMException('服务器响应超时，请稍后重试。','TimeoutError')),method==='GET'?12000:20000);}
 try{let res;try{res=await fetch(path,{method,signal,headers:{...(body?{'Content-Type':'application/json'}:{}),...(token?{Authorization:'Bearer '+token}:{}),...(method==='GET'&&options.etag?{'If-None-Match':options.etag}:{})},body:body?JSON.stringify(body):undefined});}catch(error){if(signal?.aborted)throw signal.reason||error;throw new Error('暂时无法连接游戏服务器，请稍后重试。');}
  if(res.status===304){const raw=res.headers?.get?.('X-Server-Time');return {notModified:true,serverTime:raw!=null&&Number.isFinite(Number(raw))?Number(raw):undefined,etag:res.headers?.get?.('ETag')||options.etag||null};}
  let data;try{data=await res.json();}catch(error){if(signal?.aborted)throw signal.reason||error;throw new Error('服务器返回了无法读取的响应。');}
  if(!res.ok||data.ok===false){const error=new Error(data.error||'请求失败，请稍后重试。');error.status=res.status;error.code=data.code;error.confirmedRejected=true;throw error;}const etag=res.headers?.get?.('ETag');if(etag&&data&&typeof data==='object')data.etag=etag;return data;
 }finally{clearTimeout(timer);if(controller){roomRequests.delete(controller);options.signal?.removeEventListener('abort',forwardAbort);}}
}
async function loadConfig(){if(config)return config;config=await api('/api/config');return config;}
function hostState(god){return god?.status||(!god?'waiting':god.provider!=='deepseek'&&god.reason&&!['calls-disabled','template-mode'].includes(god.reason)?'fallback':'ready');}
function hostProviderLabel(god){const state=hostState(god),source=god?.provider==='deepseek'?'DeepSeek':'模板主持';return state==='generating'?'DeepSeek · 正在撰写':state==='error'?source+' · 暂不可用':state==='fallback'?'模板主持 · 接替播报':source;}
function hostText(god){return god?.text||(hostState(god)==='generating'?'主持正在整理这一轮的播报。':hostState(god)==='error'?'本条播报暂未完成，可以继续经营并稍后查看。':'开局后，主持会在这里陪你看清每轮变化。');}
function hostBroadcastMarkup(s){const god=s.god,state=hostState(god);return `<div class="host-broadcast-label"><h2>酒馆主持</h2><span class="host-provider" data-state="${state}">${esc(hostProviderLabel(god))}</span></div><p class="host-broadcast-text" role="status" aria-live="polite">${esc(hostText(god))}</p><div class="host-broadcast-actions"><button data-action="host-latest" aria-label="展开最新主持播报与知识引用">展开</button><button data-action="host-history" aria-label="查看主持往期播报">往期</button></div>`;}
function hostKnowledgeMarkup(refs,messageId='latest'){return Array.isArray(refs)&&refs.length?`<section class="host-knowledge-list" aria-label="本条播报引用的知识"><h3>引用知识</h3>${refs.map((ref,index)=>`<details class="host-knowledge" data-knowledge="${esc(messageId+':'+(ref.id||index))}"><summary>${esc(ref.title||'知识条目')}</summary>${ref.chapter||ref.section?`<p class="host-knowledge-location">${esc([ref.chapter,ref.section].filter(Boolean).join(' · '))}</p>`:''}<p>${esc(ref.summary||ref.text||'本条目未提供摘要。')}</p>${ref.source||ref.sourceType||ref.version?`<p class="host-knowledge-source">${esc([ref.source,ref.sourceType,ref.version].filter(Boolean).join(' · '))}</p>`:''}</details>`).join('')}</section>`:'<p class="host-knowledge-empty">本条播报未附知识引用。</p>';}
function hostMessageMarkup(god,index=0){return `<article class="host-message"><header><span>${esc(hostProviderLabel(god))}</span><span>${god.round?`第 ${esc(god.round)} 轮`:'开局'}</span></header><p class="host-message-text">${esc(hostText(god))}</p>${hostState(god)==='fallback'?'<p class="host-fallback-note">模型播报暂不可用，本条由模板接替，经营可以继续。</p>':''}${hostKnowledgeMarkup(god.knowledgeRefs,god.id||[god.round,god.generatedAt,god.provider,index].join(':'))}${god.reason?`<details class="host-message-meta"><summary>播报详情</summary><p>${esc(god.reason)}</p>${god.generatedAt?`<p>${esc(new Date(god.generatedAt).toLocaleString('zh-CN'))}</p>`:''}</details>`:''}</article>`;}
function updateHostDialog(s){const content=$('#host-dialog-content');if(!content||$('#modal')?.dataset.panel!=='host')return;const open=[...content.querySelectorAll('details[open]')].map(d=>d.dataset.knowledge).filter(Boolean),scroll=content.scrollTop;
 const history=Array.isArray(s.godHistory)?s.godHistory:[],messages=hostDialogMode==='history'?history.slice().reverse():s.god?[s.god]:[];
 const html=messages.length?messages.map(hostMessageMarkup).join(''):`<div class="panel-empty"><h3>${hostDialogMode==='history'?'还没有往期播报':'主持还没开场'}</h3><p>完成的播报会按回合保存在这里。</p></div>`;
 if(setMarkup(content,html)){for(const detail of content.querySelectorAll('details[data-knowledge]'))if(open.includes(detail.dataset.knowledge))detail.open=true;content.scrollTop=scroll;}
 document.querySelectorAll('[data-action=host-view]').forEach(button=>setAttr(button,'aria-pressed',String(button.dataset.view===hostDialogMode)));
}
function updateHostBroadcast(s){setMarkup($('#host-broadcast-content'),hostBroadcastMarkup(s));if($('#modal')?.open)updateHostDialog(s);}
function openHostDialog(mode='latest'){if(!currentState)return;closeRoomSheets();hostDialogMode=mode;modal('酒馆主持',`<nav class="host-dialog-tabs" aria-label="主持播报"><button data-action="host-view" data-view="latest">最新播报</button><button data-action="host-view" data-view="history">往期播报</button></nav><div id="host-dialog-content"></div>`);$('#modal').dataset.panel='host';updateHostDialog(currentState);$('#modal [data-action=host-view]')?.focus({preventScroll:true});}

async function refreshHostDisclosure(){
 const element=$('#host-disclosure');if(!element)return;
 try{const health=await api('/api/health'),host=health.host||{enabled:health.provider==='deepseek',configuredProvider:health.provider};if(!element.isConnected)return;
  const exhausted=host?.enabled&&Number(host.limit)>0&&Number(host.calls)>=Number(host.limit);
  const message=exhausted?'本次主持调用额度已用完，模板会继续主持完整对局。':host?.enabled?(host.lastSuccessAt?'DeepSeek 主持可用，失败或用尽额度时由模板接替。':'DeepSeek 主持已启用，开局后生成公开播报；失败时由模板接替。'):host?.configuredProvider==='deepseek'&&host.keyConfigured?'DeepSeek 已配置，当前使用模板主持。':'当前使用模板主持。';
  element.textContent=message+'练习房的另外三席为脚本，四人房通过邀请链接入席，人数到齐后由房主开局。';
 }catch{if(element.isConnected)element.textContent='暂时无法确认主持连接。练习房的另外三席为脚本，四人房通过邀请链接入席，人数到齐后由房主开局。';}
}
function tavernLanding(){const invited=invitationRoom();if(invited&&credentials(invited)){consumeInvitation();go('tavern/'+invited);return;}main.innerHTML=classroomEntry({invited,sessions});prepareInvitationEntry();void refreshHostDisclosure();}
function prepareInvitationEntry(){const invited=invitationRoom();setEntryMode(document,'join');const form=$('#room-form');if(invited&&form)form.elements.roomId.value=invited;}
function invitationUrl(roomId){const url=new URL('/',location.origin);url.searchParams.set('room',roomId);url.hash='/tavern';return url.href;}
async function copyInvitation(){
 if(!currentState)return;
 if(currentState.mode==='practice'){modal('这是单人练习','<p>这张桌只有你与三位脚本对手。如需邀请朋友，请返回酒馆入口新建“四人同桌”。</p>');return;}
 const url=invitationUrl(currentState.id);
 try{await navigator.clipboard.writeText(url);toast('邀请链接已复制，发给朋友即可填写称呼入席。');}
 catch{modal('邀请朋友入席',`<p>把下面链接发给朋友。链接只含房间号，不含你的个人凭据。</p><input id="invite-link" aria-label="邀请链接" readonly value="${esc(url)}"><p>选择并复制这条链接。</p>`);$('#invite-link').select();}
}
function credentials(id){return sessions[id];}
function roomAbort(){return new DOMException('已离开此房间。','AbortError');}

function roomIsActive(id,epoch=roomEpoch){const base='#/tavern/'+id;return epoch===roomEpoch&&(location.hash===base||(location.hash.startsWith(base)&&/^\/review\/[1-6]$/.test(location.hash.slice(base.length))));}

function stopRoomSync(){roomEpoch++;clearTimeout(pollId);clearInterval(clockId);pollId=null;clockId=null;pollController?.abort();pollController=null;for(const controller of roomRequests)controller.abort();roomRequests.clear();pollFailures=0;roomEtag=null;roomEtagOwner=null;scenePlayersKey='';lastClockKey='';}

function scheduleRoomPoll(id,epoch,delay=1000){clearTimeout(pollId);if(roomIsActive(id,epoch)&&!document.hidden)pollId=setTimeout(()=>pollRoom(id,epoch),delay);}

function currentRoomEtag(id,epoch=roomEpoch){return roomEtagOwner?.epoch===epoch&&roomEtagOwner.id===id&&roomEtagOwner.token===credentials(id)?.token?roomEtag:null;}
function rememberRoomEtag(id,epoch,etag){roomEtag=typeof etag==='string'&&etag?etag:null;roomEtagOwner=roomEtag?{id,epoch,token:credentials(id)?.token}:null;}
function acceptRoomNotModified(data,id,epoch,started,sentTag){if(!roomIsActive(id,epoch)||currentState?.id!==id||!sentTag||currentRoomEtag(id,epoch)!==sentTag||(data.etag&&data.etag!==sentTag))return false;if(Number.isFinite(data.serverTime)){serverOffset=(started+Date.now())/2-data.serverTime;currentState.serverTime=data.serverTime;}rememberRoomEtag(id,epoch,data.etag||sentTag);updateRoomClock();return true;}
function acceptRoomState(next,epoch=roomEpoch,started=Date.now(),etag=null){
 if(!next||!roomIsActive(next.id,epoch))return false;
 if(currentState?.id===next.id){const oldVersion=Number(currentState.version||0),version=Number(next.version||0);if(version<oldVersion||(version===oldVersion&&Number(next.serverTime||0)<Number(currentState.serverTime||0)))return false;}
 currentState=next;rememberRoomEtag(next.id,epoch,etag);if(Number.isFinite(next.serverTime))serverOffset=(started+Date.now())/2-next.serverTime;
 if(viewKey!==`${next.id}-${next.phase}-${next.round}`)renderGame();else updateGame();return true;
}

function updateRoomClock(){if(!currentState||document.hidden)return;const s=currentState,remaining=s.deadline==null?0:Math.max(0,Math.ceil((s.deadline-(Date.now()-serverOffset))/1000)),key=`${s.id}:${s.round}:${s.phase}:${remaining}`;if(lastClockKey===key)return;lastClockKey=key;const el=$('#countdown');if(el){setMarkup(el,`${remaining}<span>秒</span>`);el.classList.toggle('urgent',remaining<=10);}updateReceipt();}

async function openRoom(id){const credential=credentials(id),epoch=roomEpoch;if(!credential){main.innerHTML=`<div class="page room-missing"><h1>这张桌，<br>还没有你的席位。</h1><p>首次加入请在入口输入代码；已有凭据可在原浏览器恢复。</p>${link('前往入席 →','tavern','button solid')}</div>`;return;}
 try{await loadConfig();if(!roomIsActive(id,epoch))return;const started=Date.now(),data=await api('/api/rooms/'+id,{token:credential.token});if(!roomIsActive(id,epoch))return;acceptRoomState(data.state,epoch,started,data.etag);clockId=setInterval(updateRoomClock,250);scheduleRoomPoll(id,epoch);}
 catch(error){if(!roomIsActive(id,epoch)||error.name==='AbortError')return;main.innerHTML=`<div class="page room-missing"><h1>暂时没能<br>回到这张桌。</h1><p>${esc(error.message)}</p><button class="button solid" data-action="retry-room" data-id="${esc(id)}">重试连接 →</button>${link('返回酒馆入口','tavern')}</div>`;}
}

async function pollRoom(id,epoch=roomEpoch){if(!roomIsActive(id,epoch)||document.hidden||pollController)return;const controller=new AbortController(),started=Date.now(),etag=currentRoomEtag(id,epoch);pollController=controller;
 try{const data=await api('/api/rooms/'+id,{token:credentials(id)?.token,signal:controller.signal,etag});if(!roomIsActive(id,epoch))return;pollFailures=0;if(data.notModified)acceptRoomNotModified(data,id,epoch,started,etag);else acceptRoomState(data.state,epoch,started,data.etag);const el=$('#connection-status');if(el){el.classList.remove('offline');setText(el,'');}}
 catch(error){if(!roomIsActive(id,epoch)||error.name==='AbortError')return;pollFailures++;const el=$('#connection-status');if(el){el.classList.add('offline');setText(el,'连接中断 · 正在重试');}}
 finally{if(pollController===controller)pollController=null;if(roomIsActive(id,epoch))scheduleRoomPoll(id,epoch,pollFailures?Math.min(8000,1000*2**pollFailures):currentState?.phase==='finished'?3000:1000);}
}
function actionName(id){return config?.actions?.find(a=>a.id===id)?.name||id||'等待选择';}
function playerDisplayName(player){const name=String(player?.name||'');return player?.isBot?name.split('·')[0].trim():name;}
function phaseName(s){return {lobby:'等待入席',preparing:'开局准备',decision:'共同决策',settling:'锁单结算',finished:'本局结束'}[s.phase]||s.phase;}
// V3 room: persistent scene, fixed information architecture, one action surface.
const roomRequests=new Set();
let roomEtag=null,roomEtagOwner=null;
let roomEpoch=0,clockId=null,pollController=null,pollFailures=0,scenePlayersKey='',lastClockKey='',hostDialogMode='latest';
let sceneQuality=getStore('sceneQuality','auto');if(!['auto','low','high'].includes(sceneQuality))sceneQuality='auto';
let submissionUncertain=false,unconfirmedAction=null;
let roomUi={tab:'world',seatId:null,sheet:null,actionOpen:false,history:false,reviewRound:null,sceneExpanded:false},draftState=null,submitting=false,submissionError='';
const roomActionKey=s=>`${s.id}:${s.round}`;
const actionFingerprint=a=>JSON.stringify(a&&{id:a.id,target:Number(a.target),scale:Number(a.scale)});
function currentDraft(s=currentState){return draftState?.key===roomActionKey(s)?draftState.action:s.me?.action||{id:config?.actions?.[0]?.id||'A12',target:0,scale:1};}
function storeDraft(){if(!currentState||!$('#action-id'))return;updateActionEstimate();draftState={key:roomActionKey(currentState),action:selectedAction(),dirty:actionFingerprint(selectedAction())!==actionFingerprint(currentState.me?.action)};submissionError='';updateActionEstimate();updateReceipt();updateAgentConnection(currentState);}
function setMarkup(element,markup){if(!element||element.__markup===markup)return false;element.innerHTML=markup;element.__markup=markup;return true;}
function setText(element,text){if(element&&element.textContent!==String(text))element.textContent=String(text);}
function setAttr(element,name,value){if(element&&element.getAttribute(name)!==String(value))element.setAttribute(name,String(value));}
function setDisabled(element,value){if(element&&element.disabled!==value)element.disabled=value;}
function targetName(s,target){const x=s.product?.segments?.[target];return typeof x==='object'?x.name||x.id:String(x||'');}
function roomPhaseMarkup(s){const full=s.phase==='lobby'?'等待入席':s.phase==='finished'?`已完成 ${s.history?.length||0} / ${s.totalRounds||6} 轮`:`第 ${s.round} / 6 轮 · ${phaseName(s)}`;const short=s.phase==='lobby'?'等待入席':s.phase==='finished'?'本局结束':`R${s.round}/6 · ${({preparing:'准备',decision:'决策',settling:'结算'})[s.phase]||''}`;return `<span id="phase-label"><span class="phase-full">${full}</span><span class="phase-short">${short}</span></span>${['preparing','decision','settling'].includes(s.phase)?'<strong id="countdown" aria-live="off"></strong>':''}`;}
function agentEntryMarkup(s){return `<button type="button" class="agent-connect-entry" data-action="agent" data-connected="${Boolean(s.me.agentConnected)}" aria-label="${s.me.agentConnected?'我的 Agent，已通过连接自检':'连接我的 Agent，复制接入指令'}"><svg viewBox="0 0 24 24" width="17" height="17" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><rect x="8" y="8" width="12" height="13" rx="2"/><path d="M16 8V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v10a2 2 0 0 0 2 2h3"/></svg><span class="agent-entry-long">${s.me.agentConnected?'我的 Agent · 已连接':'连接我的 Agent'}</span><span class="agent-entry-short">${s.me.agentConnected?'我的 Agent':'连接 Agent'}</span></button>`;}
function roomMenu(s){return `<details class="room-menu"><summary aria-label="更多房间选项"><span class="room-menu-label">更多</span><span aria-hidden="true">⌄</span></summary><div class="room-menu-content"><p class="menu-room-code">${s.mode==='practice'?'练习房':'房间'} ${esc(s.id)}</p>${s.mode==='multiplayer'?'<button data-action="copy-room">邀请朋友</button>':''}<button data-action="edit-avatar">更换我的头像</button><button data-action="agent">Agent 设置</button><button data-action="rules">规则与帮助</button><details class="scene-menu"><summary>沙盘视图</summary><label class="scene-quality-label">显示质量<select id="scene-quality" aria-label="场景显示质量">${[['auto','自动'],['low','节能'],['high','清晰']].map(([value,label])=>`<option value="${value}" ${sceneQuality===value?'selected':''}>${label}</option>`).join('')}</select></label><div><button data-action="globe-out" aria-label="缩小球体">缩小</button><button data-action="globe-in" aria-label="放大球体">放大</button><button data-action="globe-auto" aria-pressed="${autoRotate}">${autoRotate?'停止旋转':'开启旋转'}</button></div></details><a href="#/map">回到阅读</a></div></details>`;}
function economyMarkup(s,mobile=false){const me=s.players.find(p=>p.id===s.me?.id);if(!me)return '';return mobile?`<div><span>现金</span><b>${num(me.cash)}</b></div><div><span>综合分 <small>第${me.rank||'—'}名</small></span><b>${fmt(me.score)}</b></div><div><span>有效用户</span><b>${num(Math.round(me.users))}</b></div>`:`<div class="economy-heading"><span>我的经营</span><span class="my-rank">第 ${me.rank||'—'} 名</span></div><div class="cash-line"><span>现金</span><strong>${num(me.cash)}</strong></div><dl class="economy-secondary"><div><dt>综合分</dt><dd>${fmt(me.score)}${me.delta?`<small class="${me.delta>0?'positive':'negative'}">${me.delta>0?'+':''}${fmt(me.delta)}</small>`:''}</dd></div><div><dt>有效用户</dt><dd>${num(Math.round(me.users))}</dd></div></dl>`;}
function gameMarkup(s){return `<div id="room-main" class="game-page arena v3-room" data-room="${esc(s.id)}" data-sheet="" data-action-open="false"><header class="arena-hud"><div class="arena-room"><a class="arena-back" href="#/tavern" aria-label="返回酒馆入口">←</a><div><h1>增长酒馆</h1><p class="room-product-name"><span class="room-product-title">${esc(s.product?.name)}</span>${s.mode==='practice'?'<span class="practice-label">练习 · 3席脚本</span>':''}</p></div></div><div class="arena-phase">${roomPhaseMarkup(s)}</div><div class="arena-tools">${agentEntryMarkup(s)}${roomMenu(s)}</div></header><div id="connection-status" class="room-connection-warning" role="status" aria-live="polite"></div><div id="mobile-economy" class="mobile-economy">${economyMarkup(s,true)}</div><div class="game-body"><div class="arena-main"><div id="classroom-result-slot"></div><div id="classroom-mission-slot"></div><section class="arena-stage" aria-label="四人圆桌经营场景"><div id="globe-container" class="globe-container" aria-label="四位经营者围坐的三维圆桌"></div><button class="scene-toggle" data-action="scene-toggle" aria-pressed="false">展开圆桌</button></section><section id="host-broadcast" class="host-broadcast" aria-label="酒馆主持播报"><div id="host-broadcast-content">${hostBroadcastMarkup(s)}</div></section><button class="mobile-intel-peek" aria-controls="insight-panel" data-action="open-panel" data-panel="world"><span>本轮情报</span><b id="world-preview">开局后发布</b><span aria-hidden="true">↗</span></button><div id="classroom-round-summary-slot"></div><section class="decision-panel arena-dock" id="decision-panel" aria-label="本轮行动">${decisionMarkup(s)}</section></div><aside id="insight-panel" class="insight-panel" aria-label="经营数据与对局信息"><header class="mobile-sheet-header"><h2>桌上消息</h2><button data-action="close-sheet" class="icon-button" aria-label="关闭信息面板">×</button></header><div id="economy-summary" class="economy-summary">${economyMarkup(s)}</div><nav class="insight-tabs" aria-label="桌上信息" role="tablist">${[['world','情报'],['research','研究'],['ledger','账本']].map(([id,name])=>`<button role="tab" id="tab-${id}" aria-controls="insight-content" aria-selected="${roomUi.tab===id}" data-action="insight-tab" data-panel="${id}">${name}</button>`).join('')}</nav><div id="insight-content" class="insight-content" role="tabpanel" aria-labelledby="tab-${roomUi.tab}"></div></aside></div><button class="sheet-scrim" data-action="close-sheet" aria-label="关闭展开面板" tabindex="-1"></button></div>`;}
function decisionMarkup(s){const me=s.me||{},player=s.players.find(p=>p.id===me.id);
 if(s.phase==='lobby')return `<div class="phase-message"><span class="phase-kicker">${s.mode==='practice'?'单人练习':'等待入席'} · ${s.players.length}/4</span><h2>${s.players.length<4?'给朋友留了位子':'这一桌，准备好了'}</h2><p>${s.mode==='practice'?'另三席由经营脚本扮演，随时可以开始。':s.players.length<4?'把邀请链接发给朋友，人齐后开局。':'四位经营者已经入席，由房主开始这一局。'}</p><ul class="lobby-seat-status">${Array.from({length:4},(_,seat)=>{const p=s.players.find(p=>p.seat===seat);return `<li class="${p?'occupied':'vacant'}"><i style="--seat-color:${p?esc(p.color):'#706a5e'}"></i><span title="${p?esc(p.name):'等待朋友'}">${p?esc(playerDisplayName(p)):'等待朋友'}${p?.id===me.id?' · 你':''}</span></li>`;}).join('')}</ul></div><div class="phase-actions">${s.hostId===me.id?`<button class="button solid" data-action="start" ${s.players.length<4?'disabled':''}>${s.players.length<4?'等待四位玩家':'开始经营'}</button>`:'<span class="muted">等待房主开局</span>'}${s.mode==='multiplayer'?'<button class="button outline" data-action="copy-room">邀请朋友</button>':''}</div>`;
 if(s.phase==='preparing'||s.phase==='settling')return `<div class="phase-message"><span class="phase-kicker">第 ${s.round} 轮</span><h2>${s.phase==='preparing'?'看看本轮发生了什么':'行动已锁定，正在结算'}</h2><p>${s.phase==='preparing'?'准备结束后，会有完整 45 秒选择行动。':'这时不能更改行动，结果会显示在右侧账本。'}</p></div><div class="phase-actions">${s.mode==='practice'?'<button class="button solid" data-action="advance">继续</button>':'<button class="button outline" data-action="open-panel" data-panel="world">查看情报</button>'}</div>`;
 if(s.phase==='finished')return `<div class="phase-actions classroom-finished-actions"><a class="button outline" href="#/tavern">再开一桌</a><button class="quiet-button" data-action="download-replay">导出完整回放</button><button class="quiet-button" data-action="scene-toggle">再看看圆桌</button></div>`;
 const action=currentDraft(s),catalog=config?.actions||[],definition=catalog.find(a=>a.id===action.id)||catalog[0];
 return `<div class="mobile-action-bar"><div><span class="mobile-action-state" id="mobile-action-state">${me.action?'已接收':'本轮尚未提交'}</span><b id="mobile-action-title">${esc(actionName(action.id))}</b></div><button class="button solid" data-action="toggle-action-sheet">${me.action?'更新行动':'选择行动'}</button></div><div class="action-editor"><header class="action-editor-header"><h2>这一轮，怎么经营？</h2><button class="icon-button" data-action="close-action-sheet" aria-label="关闭行动面板">×</button></header><div class="dock-status"><div id="receipt-status" class="receipt-status" role="status" aria-live="polite"></div><span id="agent-connected" class="agent-mode">${me.authorization==='autopilot'?'Agent 托管':me.agentConnected?'Agent 建议':'手动决策'}</span></div><div id="suggestion-slot"></div>${s.round===1&&!getStore('firstTurnHelpDismissed',false)?'<aside class="classroom-first-turn"><p>先看情报，再核对行动、人群与预算。默认草稿不是推荐，确认后才提交。</p><button type="button" class="quiet-button" data-action="dismiss-first-turn">知道了</button></aside>':''}${actionContextMarkup(s)}${actionPurposeMarkup()}<form id="action-form"><div class="action-fields"><label>行动<select id="action-id" name="actionId">${actionOptions(catalog,action.id)}</select></label><label id="action-target-label">目标人群<select id="action-target" name="target">${(s.product?.segments||[]).map((x,i)=>`<option value="${i}" ${Number(action.target)===i?'selected':''}>${esc(typeof x==='object'?x.name||x.id:x)}</option>`).join('')}</select></label><label>投入<select id="action-scale" name="scale">${(definition?.scales||[1]).map(v=>`<option value="${v}" ${Number(action.scale)===v?'selected':''}>${v===.5?'轻量':v===1?'标准':'加码'} ×${v}</option>`).join('')}</select></label></div><div class="action-footer"><div class="action-cost-copy"><p id="action-estimate" class="action-estimate"></p><p id="action-description" class="action-description"></p><button type="button" class="quiet-button" id="action-concept-link" data-action="concept" data-concept="K06">理解这个行动背后的方法</button></div><button type="submit" class="button solid" ${player?.bankrupt?'disabled':''}>${me.action?'更新行动':'确认行动'}</button></div><p class="form-error" id="action-error" role="alert"></p><div class="dock-secondary"><details class="action-options"><summary>更多操作</summary><div><button type="button" class="quiet-button" data-action="save-default">设为超时默认</button><button type="button" class="quiet-button" data-action="open-panel" data-panel="intent">告诉 Agent 我的想法</button>${s.mode==='practice'?'<button type="button" class="quiet-button practice-advance" data-action="advance">练习：提前结算</button>':''}</div></details><span id="default-description"></span></div></form></div>`;
}
function setRoomSheets(){const arena=$('.v3-room');if(!arena)return;if(arena.dataset.sheet!==(roomUi.sheet||''))arena.dataset.sheet=roomUi.sheet||'';if(arena.dataset.actionOpen!==String(roomUi.actionOpen))arena.dataset.actionOpen=String(roomUi.actionOpen);const panel=$('#insight-panel');setAttr(panel,'aria-hidden',String(matchMedia('(max-width:900px)').matches&&roomUi.sheet!=='info'));}
function renderGame(){const s=currentState;if(!s)return;const key=`${s.id}-${s.phase}-${s.round}`,arena=$('.v3-room');if(!arena||arena.dataset.room!==s.id){roomUi={tab:'world',seatId:null,sheet:null,actionOpen:false,history:false,reviewRound:null,sceneExpanded:false};draftState=null;submissionError='';submissionUncertain=false;unconfirmedAction=null;globe?.destroy();main.innerHTML=gameMarkup(s);globe=mountGlobe($('#globe-container'),s.players,{autoRotate,quality:sceneQuality,meId:s.me?.id,onSeatClick:openSeatDetails,onAvatarClick:player=>player?.id===currentState?.me?.id?showAvatarEditor():openSeatDetails(player),onAutoRotateChange:value=>{autoRotate=value;const b=$('[data-action=globe-auto]');if(b){b.textContent=value?'停止旋转':'开启旋转';b.setAttribute('aria-pressed',String(value));}}});}else if(viewKey!==key){draftState=null;submissionError='';submissionUncertain=false;unconfirmedAction=null;submitting=false;roomUi.actionOpen=false;$('.arena-phase').innerHTML=roomPhaseMarkup(s);$('#decision-panel').innerHTML=decisionMarkup(s);}viewKey=key;document.body.dataset.gamePhase=s.phase;const requested=location.hash.split('/');if(requested[3]==='review'&&Number(requested[4])>=1&&Number(requested[4])<=6)roomUi.reviewRound=Number(requested[4]);updateGame();setRoomSheets();}
function updateReceipt(){if(!currentState)return;const s=currentState,me=s.me||{},draft=currentDraft(s);let dirty=draftState?.key===roomActionKey(s)&&draftState.dirty;let state='unsubmitted',text='本轮尚未提交';const expired=s.phase==='decision'&&s.deadline!=null&&Date.now()-serverOffset>=s.deadline;if(submissionUncertain&&unconfirmedAction?.key===roomActionKey(s)&&actionFingerprint(me.action)===actionFingerprint(unconfirmedAction.action)){if(actionFingerprint(currentDraft(s))===actionFingerprint(unconfirmedAction.action)){draftState={key:roomActionKey(s),action:structuredClone(me.action),dirty:false};dirty=false;}submissionUncertain=false;submissionError='';unconfirmedAction=null;if($('#action-error'))$('#action-error').textContent='';}if(expired){state='locked';text='截止已到，等待统一结算';}else if(submitting){state='submitting';text='正在提交，请稍候';}else if(submissionError){state=submissionUncertain?'uncertain':'error';text=submissionUncertain?'尚未确认结果，正在同步':me.action?'更新未成功，原行动仍有效':'提交未成功，请重试';}else if(dirty&&me.action){state='draft';text=`正在修改 · 已接收 ${actionName(me.action.id)}`;}else if(me.action){state='accepted';text=`已接收 ${actionName(me.action.id)}`;}else if(dirty){state='draft';text='草稿已选择，确认后才会执行';}const el=$('#receipt-status');if(el){if(el.dataset.state!==state)el.dataset.state=state;setMarkup(el,`<span class="status-dot ${state==='accepted'?'':'waiting'}" aria-hidden="true"></span><b>${esc(text)}</b>`);}setText($('#mobile-action-state'),({accepted:'服务端已接收',submitting:'正在提交',error:'提交未成功',uncertain:'结果待确认',locked:'已截止 · 等待结算',draft:me.action?'有未提交修改':'草稿未提交',unsubmitted:'本轮尚未提交'})[state]);const mobileButton=$('[data-action=toggle-action-sheet]');if(mobileButton){setText(mobileButton,me.action?'更新行动':'选择行动');setDisabled(mobileButton,submitting||expired||Boolean(s.players.find(p=>p.id===me.id)?.bankrupt));}setText($('#mobile-action-title'),actionName(draft?.id));const submit=$('#action-form button[type=submit]');if(submit){setText(submit,submitting?'正在提交':me.action?'更新行动':'确认行动');setDisabled(submit,submitting||expired||Boolean(s.players.find(p=>p.id===me.id)?.bankrupt));}}
function updateGame(){const s=currentState;if(!s)return;const me=s.me||{},remaining=s.deadline==null?0:Math.max(0,Math.ceil((s.deadline-(Date.now()-serverOffset))/1000));const connection=$('#connection-status');if(connection){connection.classList.remove('offline');connection.textContent='';}updateRoomClock();const playersKey=JSON.stringify(s.players);if(playersKey!==scenePlayersKey){scenePlayersKey=playersKey;globe?.update(s.players);}updateHostBroadcast(s);updateClassroomSurfaces(s);setMarkup($('#economy-summary'),economyMarkup(s));setMarkup($('#mobile-economy'),economyMarkup(s,true));
 if($('#action-form')&&!draftState?.dirty&&!submitting&&me.action){const a=me.action;if($('#action-id').value!==a.id||Number($('#action-target').value)!==Number(a.target)||Number($('#action-scale').value)!==Number(a.scale)){applyActionToInputs(a);}}
 updateActionEstimate();updateReceipt();updateAgentConnection(currentState);setText($('#default-description'),remaining<=10&&!me.action?`超时将执行：${actionName(me.defaultAction?.id)} ×${me.defaultAction?.scale||1}`:'');setText($('#agent-connected'),me.authorization==='autopilot'?'Agent 托管':me.agentConnected?'Agent 建议':'手动决策');
 const suggestion=me.suggestion;setMarkup($('#suggestion-slot'),suggestion?`<div class="agent-suggestion"><div><b>Agent 建议 · ${esc(actionName(suggestion.action?.id||suggestion.id))}</b><p>${esc(suggestion.summary||'核对目标与预算后再确认。')}</p></div><button type="button" class="quiet-button" data-action="accept-suggestion">采用建议</button></div>`:'');
 const latest=(s.world||[]).slice().reverse().find(w=>w.round===s.round&&w.type==='fact')||s.world?.at(-1);setText($('#world-preview'),latest?.text||(s.phase==='lobby'?'开局后发布公开情报':'查看本轮情报'));
 updatePanel(s);if(s.phase==='lobby'&&$('#decision-panel')?.dataset.players!==String(s.players.length)){$('#decision-panel').innerHTML=decisionMarkup(s);$('#decision-panel').dataset.players=String(s.players.length);}setRoomSheets();}
function worldMarkup(s){const names={fact:'事实',forecast:'有限预告',rumor:'未核实传闻',verification:'核验结果'},all=(s.world||[]).slice().reverse(),messages=roomUi.history?all:all.filter(w=>w.round===s.round||w.endRound>=s.round);return `<div class="feed-heading"><h2>${roomUi.history?'全部情报':'本轮情报'}</h2>${all.length?`<button class="quiet-button" data-action="toggle-history">${roomUi.history?'只看本轮':'查看往期'}</button>`:''}</div><div class="world-feed">${messages.length?messages.map(w=>`<article class="world-message ${esc(w.type)}"><header><span class="world-type">${names[w.type]||'播报'}</span><span>第 ${w.round||0} 轮</span></header><p>${esc(w.text)}</p></article>`).join(''):`<div class="panel-empty"><h3>${s.phase==='lobby'?'入席后，一起看消息':'这一轮没有新增情报'}</h3><p>${s.phase==='lobby'?'开局后会发布事实、预告与待核验传闻。':'可以查看往期信息，或先考虑本轮经营行动。'}</p></div>`}</div>`;}
function researchMarkup(s){const notes=s.me?.privateNotes||[];return `<div class="feed-heading"><h2>我的研究</h2><span>仅本人可见</span></div>${notes.length?notes.slice().reverse().map(n=>`<article class="research-result"><header>第 ${n.round} 轮 · ${n.type==='research'?'用户访谈':'对照实验'} · ${esc(targetName(s,n.target))}</header>${n.type==='research'?`<h3>引导响应 ${fmt(n.onboarding)}<br>习惯响应 ${fmt(n.habit)}</h3>`:`<h3>${esc(n.verdict)}</h3><p>差值 ${fmt(n.difference*100)} 个百分点<br>对照 ${n.controlSuccess}/${n.controlN} · 实验 ${n.treatmentSuccess}/${n.treatmentN}</p><p class="small">保守区间 [${fmt(n.interval?.[0]*100)}, ${fmt(n.interval?.[1]*100)}]</p>`}<p>${esc(n.text)}</p></article>`).join(''):'<div class="panel-empty"><span class="empty-symbol" aria-hidden="true">∿</span><h3>先问一个好问题</h3><p>进行用户调研或对照实验后，你得到的私有结果会保存在这里。</p></div>'}`;}
function ledgerMarkup(s){const sorted=[...s.players].sort((a,b)=>a.rank-b.rank||a.seat-b.seat);return `<div class="feed-heading"><h2>同桌经营</h2><span>综合分</span></div><ol class="compact-ranking">${sorted.map(p=>`<li><button data-action="seat-detail" data-id="${esc(p.id)}" title="${esc(p.name)}" aria-label="查看${esc(p.name)}的公开经营资料"><span class="ranking-position">${p.rank||'—'}</span><span class="ranking-name"><i style="background:${esc(p.color)}"></i><span class="ranking-label">${esc(playerDisplayName(p))}</span>${p.id===s.me?.id?'<small>你</small>':''}</span><b>${fmt(p.score)}</b></button></li>`).join('')}</ol><div class="feed-heading"><h2>回合记录</h2><span>${s.history?.length||0} / 6</span></div>${s.history?.length?`<details class="history-details"><summary>展开六轮对照表</summary><div class="history-table-wrap"><table><caption>综合分、有效用户与累计利润</caption><thead><tr><th>回合</th>${s.players.map(p=>`<th title="${esc(p.name)}">${esc(playerDisplayName(p))}</th>`).join('')}</tr></thead><tbody>${s.history.map(h=>`<tr><th>${h.round}</th>${s.players.map(p=>{const r=h.players?.find(x=>x.id===p.id||x.seat===p.seat)||{};return `<td><b>${fmt(r.score)}</b><span>用户 ${num(Math.round(r.users||0))}</span><span>利润 ${num(r.profit)}</span></td>`;}).join('')}</tr>`).join('')}</tbody></table></div></details>`:'<div class="panel-empty"><h3>第一笔账，还没开始</h3><p>首轮结算后，就能逐轮比较大家的经营结果。</p></div>'}`;}
function updatePanel(s){const content=$('#insight-content');if(!content)return;const scroll=content.scrollTop,open=[...content.querySelectorAll('details[open]')].map(d=>d.className);let html;if(roomUi.seatId){const player=s.players.find(p=>p.id===roomUi.seatId);html=player?`<button class="panel-back" data-action="back-to-info">← 返回桌上信息</button><h2 class="detail-player-name">${esc(player.name)}${player.id===s.me?.id?' · 你':''}</h2>${seatDetail(player,s)}`:'<p>这个席位暂时没有玩家。</p>';}else html=roomUi.tab==='research'?researchMarkup(s):roomUi.tab==='ledger'?ledgerMarkup(s):worldMarkup(s);if(setMarkup(content,html)){for(const cl of open){const d=[...content.querySelectorAll('details')].find(d=>d.className===cl);if(d)d.open=true;}content.scrollTop=scroll;}setAttr(content,'aria-labelledby','tab-'+roomUi.tab);document.querySelectorAll('[data-action=insight-tab]').forEach(b=>setAttr(b,'aria-selected',String(b.dataset.panel===roomUi.tab)));}
function openSeatDetails(player){if(!player||!currentState)return;roomUi.seatId=player.id;roomUi.sheet='info';roomUi.actionOpen=false;updatePanel(currentState);setRoomSheets();}
function seatDetail(p,s){return `<div class="seat-detail-score"><b>${fmt(p.score)}</b><span>综合分 · 第 ${p.rank||'—'} 名${p.bankrupt?' · 已破产':''}</span></div><dl class="seat-detail-grid"><div><dt>有效用户</dt><dd>${num(Math.round(p.users))}</dd></div><div><dt>累计利润</dt><dd>${num(p.profit)}</dd></div><div><dt>现金</dt><dd>${num(p.cash)}</dd></div><div><dt>合并留存</dt><dd>${Math.round(p.retention*100)}%</dd></div></dl><h3>分项贡献</h3><p>规模 ${fmt(p.contributions?.growth)} · 利润 ${fmt(p.contributions?.profit)} · 留存 ${fmt(p.contributions?.retention)}</p>${p.id===s.me?.id?'<button class="button outline" data-action="edit-avatar">更换我的头像</button>':''}<details class="area-explanation"><summary>球面领地如何计算？</summary><p>按本席分数÷（600＋全员分数合计）分配，包含背面。建筑和光晕不加分，也不代表真实市场份额。</p></details>`;}

function savedAvatarPreference(){
 const value=getStore('avatarPreference',null);if(value==null)return null;
 try{return normalizeAvatar(value);}catch{return null;}
}
function showAvatarEditor(){
 const s=currentState;if(!s?.me)return;
 const player=s.players.find(p=>p.id===s.me.id);if(!player)return;
 avatarEditor?.close();if($('#modal').open)$('#modal').close();
 const id=s.id,epoch=roomEpoch,credential=credentials(id)?.token;
 let editor;
 editor=openAvatarEditor({current:player.avatar,seatIndex:player.seat,onClose:()=>{if(avatarEditor===editor)avatarEditor=null;},onSave:async avatar=>{
  const d=await api('/api/rooms/'+id+'/avatar',{method:'POST',token:credential,body:{avatar}});
  if(!roomIsActive(id,epoch))throw roomAbort();saveStore('avatarPreference',avatar);
  if(d.state)acceptRoomState(d.state,epoch,Date.now(),d.etag);
  toast('头像已更新，同桌玩家也能看到。');
 }});
 avatarEditor=editor;
}
function openGamePanel(panel){if(!currentState)return;if(panel==='intent'){closeRoomSheets();modal('告诉 Agent 我的想法',`<form id="intent-form"><label for="intent-text">你的经营意图</label><textarea id="intent-text" name="text" maxlength="1000" placeholder="例如：保留现金，优先修复留存……">${esc(currentState.me.intent?.text||currentState.me.intent||'')}</textarea><p>自己的 Agent 会将意图映射为合法行动。保存意图不等于提交行动。</p><button class="button solid" type="submit">保存给 Agent</button></form>`);return;}roomUi.tab=['world','research','ledger'].includes(panel)?panel:'world';roomUi.seatId=null;roomUi.sheet='info';roomUi.actionOpen=false;updatePanel(currentState);if($('#insight-content'))$('#insight-content').scrollTop=0;setRoomSheets();}
function applyActionToInputs(action){if(!$('#action-id'))return;$('#action-id').value=action.id;$('#action-scale').dataset.action='';updateActionEstimate();$('#action-target').value=action.target;$('#action-scale').value=action.scale;updateActionEstimate();}
function selectedAction(){const fallback=currentState?currentDraft(currentState):{id:'A12',target:0,scale:1};return {id:$('#action-id')?.value||fallback.id,target:Number($('#action-target')?.value??fallback.target),scale:Number($('#action-scale')?.value??fallback.scale)};}
function updateActionEstimate(){if(!$('#action-id')||!currentState)return;const a=config.actions.find(a=>a.id===$('#action-id').value);if(!a)return;const scaleSelect=$('#action-scale');if(scaleSelect.dataset.action!==a.id){const old=Number(scaleSelect.value);scaleSelect.innerHTML=(a.scales||[1]).map(v=>`<option value="${v}" ${v===((a.scales||[1]).includes(old)?old:1)?'selected':''}>${v===.5?'轻量':v===1?'标准':'加码'} ×${v}</option>`).join('');scaleSelect.dataset.action=a.id;}const targetSelect=$('#action-target');setDisabled(targetSelect,a.scope==='all');if(a.scope==='all')targetSelect.value='0';if($('#action-target-label').hidden!==(a.scope==='all'))$('#action-target-label').hidden=a.scope==='all';const description=(typeof a?.effect==='string'?a.effect:a?.concept)||'核对预算后提交，本轮截止前可更新。';setText($('#action-description'),description);if($('#action-concept-link'))$('#action-concept-link').dataset.concept=a.concept||'K06';const cost=(typeof a?.cost==='number'?a.cost:0)*Number(scaleSelect.value),p=currentState.players.find(p=>p.id===currentState.me.id),budget=Math.max(0,(p?.cash||0)-20);setMarkup($('#action-estimate'),`<span>预计投入 <b class="${cost>budget?'over-budget':''}">${num(cost)}</b></span><span>可用预算 <b>${num(budget)}</b></span><span class="budget-reserve">已留20运营费</span>`);if($('#action-estimate').title!=='已预留20固定运营费。提交被接收后不会立即扣款，截止后统一结算。')$('#action-estimate').title='已预留20固定运营费。提交被接收后不会立即扣款，截止后统一结算。';setText($('#mobile-action-title'),a.name);}
async function submitRoomAction(action){
 if(submitting||!currentState||!action)return false;
 const epoch=roomEpoch,round=currentState.round,key=roomActionKey(currentState);submitting=true;submissionError='';submissionUncertain=false;unconfirmedAction={key,action:structuredClone(action)};if($('#action-error'))$('#action-error').textContent='';updateReceipt();
 try{await act('action',{round,action,requestId:uid()});if(epoch===roomEpoch&&currentState&&roomActionKey(currentState)===key){const accepted=currentState.me?.action||action;draftState={key,action:structuredClone(accepted),dirty:false};submissionUncertain=false;unconfirmedAction=null;applyActionToInputs(accepted);roomUi.actionOpen=false;setRoomSheets();}return true;}
 catch(error){if(epoch!==roomEpoch||error.name==='AbortError')return false;submissionError=error.message;submissionUncertain=!error.confirmedRejected;if($('#action-error'))$('#action-error').textContent=submissionUncertain?'连接中断，提交结果尚未确认。恢复连接后会自动核对。':error.message;return false;}
 finally{if(epoch===roomEpoch){submitting=false;updateReceipt();}}
}
function closeRoomSheets(){roomUi.sheet=null;roomUi.actionOpen=false;setRoomSheets();}
window.addEventListener('resize',()=>{if(currentState)setRoomSheets();},{passive:true});
document.addEventListener('keydown',event=>{if(!currentState)return;if(event.key==='Tab'&&matchMedia('(max-width:900px)').matches){const panel=roomUi.actionOpen?$('.action-editor'):roomUi.sheet==='info'?$('#insight-panel'):null;if(panel&&!$('#modal')?.open){const controls=[...panel.querySelectorAll('button:not(:disabled),a[href],input:not(:disabled),select:not(:disabled),textarea:not(:disabled),summary')].filter(el=>el.getClientRects().length);const first=controls[0],last=controls.at(-1);if(event.shiftKey&&(event.target===first||!panel.contains(event.target))){event.preventDefault();last?.focus();}else if(!event.shiftKey&&(event.target===last||!panel.contains(event.target))){event.preventDefault();first?.focus();}}} if(event.key==='Escape'){closeRoomSheets();const menu=$('.room-menu');if(menu)menu.open=false;}if(event.target.matches('[data-action=insight-tab]')&&['ArrowLeft','ArrowRight','Home','End'].includes(event.key)){event.preventDefault();const tabs=[...document.querySelectorAll('[data-action=insight-tab]')];let i=tabs.indexOf(event.target);i=event.key==='Home'?0:event.key==='End'?tabs.length-1:(i+(event.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[i].focus();roomUi.tab=tabs[i].dataset.panel;roomUi.seatId=null;updatePanel(currentState);}});

function modal(title,html){const el=$('#modal');el.dataset.panel='';el.innerHTML=`<div class="modal-header"><h2 id="modal-title">${title}</h2><button class="icon-button" data-action="close-modal" aria-label="关闭弹窗">×</button></div><div class="modal-body">${html}</div>`;if(!el.open)el.showModal();}
function updateAgentConnection(s){if(!s?.me)return;const connected=Boolean(s.me.agentConnected),entry=$('.agent-connect-entry');if(entry){if(entry.dataset.connected!==String(connected))entry.dataset.connected=String(connected);setAttr(entry,'aria-label',connected?'我的 Agent，已通过连接自检':'连接我的 Agent，复制接入指令');setText(entry.querySelector('.agent-entry-long'),connected?'我的 Agent · 已连接':'连接我的 Agent');setText(entry.querySelector('.agent-entry-short'),connected?'我的 Agent':'连接 Agent');}const status=$('#agent-modal-connection');if(status){if(status.dataset.connected!==String(connected))status.dataset.connected=String(connected);setText(status,connected?'已连接 · 服务器已收到 Agent 自检':'等待 Agent 自检 · 复制后还需粘贴并执行');}const mode=$('#agent-current-mode');setText(mode,s.me.authorization==='autopilot'?'当前为自主模式 · Agent 可直接提交行动':'当前为建议模式 · 行动由你确认');}
function openAgentDialog(){if(!currentState)return;closeRoomSheets();const me=currentState.me;modal('连接自己的 Agent',`<section class="agent-copy-section" aria-labelledby="agent-copy-title"><h3 id="agent-copy-title">复制后，粘贴到你的 Agent 对话中</h3><p class="agent-copy-intro">把本席连接信息交给自己的 Agent，让它先完成连接自检。</p><button type="button" class="button solid agent-copy-button" id="copy-agent-button" data-action="copy-agent" aria-describedby="agent-copy-feedback">复制给我的 Agent</button><p id="agent-copy-feedback" class="agent-copy-feedback" role="status" aria-live="polite">包含连接地址与本席接入指令。仅交给你信任的 Agent。</p></section><div id="agent-modal-connection" class="agent-connection" role="status" aria-live="polite"></div><p id="agent-current-mode" class="agent-current-mode"></p><details id="agent-instructions" class="agent-instructions"><summary>查看完整接入指令</summary><label for="agent-prompt" class="agent-prompt-label">本席专属指令</label><textarea id="agent-prompt" class="agent-prompt" readonly spellcheck="false">${esc(agentPrompt())}</textarea><button class="quiet-button agent-revoke" data-action="rotate-agent">撤销旧凭据并重新生成</button><p class="small muted">平台不代开玩家模型，不收集供应商密钥。客户端须能访问此服务；Claude Code 与 WorkBuddy 尚待实际适配验证。</p></details><details class="agent-preferences"><summary>Agent 偏好与授权</summary><form id="profile-form" class="profile-form"><div class="form-two"><label>Agent 性格<select name="persona">${[['analytical','理性分析'],['creative','探索创新'],['pragmatic','务实经营']].map(([v,n])=>`<option value="${v}" ${me.persona===v?'selected':''}>${n}</option>`).join('')}</select></label><label>风险偏好<select name="risk">${[['low','稳健'],['medium','平衡'],['high','进取']].map(([v,n])=>`<option value="${v}" ${me.risk===v?'selected':''}>${n}</option>`).join('')}</select></label></div><label>授权<select name="authorization"><option value="assist" ${me.authorization==='assist'?'selected':''}>建议模式 · 我来确认</option><option value="autopilot" ${me.authorization==='autopilot'?'selected':''}>自主模式 · Agent可提交</option></select></label><button class="button outline small-button" type="submit">保存 Agent 偏好</button></form></details>`);$('#modal').dataset.panel='agent';updateAgentConnection(currentState);$('#copy-agent-button').focus({preventScroll:true});}
async function copyAgentInstructions(button){if(!currentState)return;const prompt=agentPrompt(),feedback=$('#agent-copy-feedback');button.disabled=true;button.textContent='正在复制…';try{if(!navigator.clipboard?.writeText)throw new Error('Clipboard unavailable');await navigator.clipboard.writeText(prompt);button.textContent='已复制 · 去粘贴给 Agent';button.dataset.copied='true';if(feedback)feedback.textContent='已复制。现在粘贴到自己的 Agent 对话中，并让它执行连接自检。';}catch{button.textContent='重新复制给我的 Agent';button.dataset.copied='false';const details=$('#agent-instructions'),field=$('#agent-prompt');if(details)details.open=true;if(field){field.value=prompt;field.focus();field.select();}if(feedback)feedback.textContent='自动复制未成功，完整指令已选中。请手动复制，再粘贴给自己的 Agent。';}finally{button.disabled=false;}}
function agentPrompt(){const s=currentState,c=credentials(s.id);return `你是增长酒馆里我自己的玩家Agent，只能访问我这一席。服务地址：${location.origin}\n房间：${s.id}\nAgent Bearer token：${c.agentToken}\n\n先 GET /api/rooms/${s.id}/agent/check 完成连接自检，然后 GET /api/rooms/${s.id}/agent/state 读取状态与我的意图，GET /api/config 查看12种行动。请求头 Authorization: Bearer <上述token>。不要读取其他本机文件或聊天，不索要供应商密钥。\n\n每轮只映射一项合法行动：POST /api/rooms/${s.id}/agent/action，JSON {"round":当前回合,"action":{"id":"A01","target":0,"scale":1},"requestId":"每次决策唯一ID","summary":"解释行动、目标、投入与风险"}。assist模式提交建议等待我确认；autopilot模式直接行动。行动须符合预算、席位、回合与服务器截止时间。读取提交回执，不把请求发送当作成功。使用inbox?since=cursor持续读取我的新意图和公开状态；断线后读取状态恢复，重试保留同一requestId。不创造机制、不组合多次行动、不访问未来事件或对手私有信息。每轮先看事实与未核实传闻的区别。${s.me.persona?`我的性格：${s.me.persona}；风险：${s.me.risk}。`:''}\n\n请先报告连接自检结果。复制这段提示词本身不代表已建立双向连接。`}
async function act(action,body={}){if(!currentState)throw roomAbort();const id=currentState.id,epoch=roomEpoch,started=Date.now(),data=await api('/api/rooms/'+id+'/'+action,{method:'POST',token:credentials(id).token,body});if(!roomIsActive(id,epoch))throw roomAbort();if(data.state)acceptRoomState(data.state,epoch,started,data.etag);return data;}
function download(name,data){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
